private boolean isChecked(int checkBoxId){
    CheckBox checkBox = (CheckBox) dialog.findViewById(checkBoxId);
    return checkBox != null && checkBox.isChecked();
}

/**
 * Reads the text of the given view and parses it as an int. Empty or
 * non numeric input is treated as 0 instead of throwing a
 * NumberFormatException.
 */
private int readInt(int textViewId){
    String value = readText(textViewId);
    if(value.isEmpty())
        return 0;
    try {
        return Integer.parseInt(value);
    } catch (NumberFormatException e) {
        return 0;
    }
}

/**
 * Reads the text of the given view and parses it as a double. Empty or
 * non numeric input is treated as 0.0 instead of throwing a
 * NumberFormatException.
 */
private double readDouble(int textViewId){
    String value = readText(textViewId);
    if(value.isEmpty())
        return 0.0;
    try {
        return Double.parseDouble(value);
    } catch (NumberFormatException e) {
        return 0.0;
    }
}

private String readText(int textViewId){
    TextView textView = (TextView) dialog.findViewById(textViewId);
    if(textView == null || textView.getText() == null)
        return "";
    return textView.getText().toString().trim();
}

